        ///   - data: The data; it may continue after the record.
        ///   - byteLimit: An optional limit on the bytes of this record.
        /// - Returns: The number of bytes the record occupies.
        /// - Throws: `GesWireError` when the data is no valid record.
        @discardableResult
        func read(from data: UnsafeRawBufferPointer, byteLimit: Int = .max) throws(GesWireError) -> Int {
            var reader = GesBitReader(data: data, byteLimit: byteLimit)
            try __readFields(&reader, Self.__paths, 0)
            return try reader.finish()
        }

        /// Reads a record from bytes into this instance. After an error its values are unspecified.
        /// - Returns: The number of bytes the record occupies.
        /// - Throws: `GesWireError` when the bytes are no valid record.
        @discardableResult
        func read(from bytes: [UInt8], byteLimit: Int = .max) throws(GesWireError) -> Int {
            let buffer = UnsafeMutableRawBufferPointer.allocate(byteCount: Swift.max(bytes.count, 1), alignment: 8)
            defer { buffer.deallocate() }
            buffer.copyBytes(from: bytes)
            return try read(from: UnsafeRawBufferPointer(rebasing: buffer[0..<bytes.count]), byteLimit: byteLimit)
        }

        /// Reads the key, which comes first, before a caller chooses a baseline.
        /// - Throws: `GesWireError` when the data ends before the key does or holds an invalid key.
        static func readKey(from data: UnsafeRawBufferPointer) throws(GesWireError) -> Int64 {
            var reader = GesBitReader(data: data)
            let paths = Self.__paths
            let at = 0
            var key: Int64 = 0
            do {
                let index = try reader.read(4, path: paths[at + 0])
                key = Int64(bitPattern: 0 &+ index)
            }
            return key
        }

        func __writeFields(_ writer: inout GesBitWriter, _ paths: [String], _ at: Int, _ level: Int = 1) throws(GesWireError) {
            if self.id < 0 || UInt64(bitPattern: self.id) &- 0 > 15 { throw GesWireError(code: GesWireError.outOfRange, path: paths[at + 0]) }
            try writer.write(UInt64(bitPattern: self.id) &- 0, width: 4)
            if level >= 3 {
                if self.units.count > 0 { throw GesWireError(code: GesWireError.tooDeep, path: paths[at + 1], detail: "deeper than depth 3") }
            } else {
                if self.units.count > 4 { throw GesWireError(code: GesWireError.tooLong, path: paths[at + 1]) }
                try writer.write(UInt64(self.units.count), width: 3)
                for item in self.units {
                    try item.__writeFields(&writer, paths, at + 3, level + 1)
                }
            }
        }

        func __readFields(_ reader: inout GesBitReader, _ paths: [String], _ at: Int, _ level: Int = 1) throws(GesWireError) {
            do {
                let index = try reader.read(4, path: paths[at + 0])
                self.id = Int64(bitPattern: 0 &+ index)
            }
            if level >= 3 {
                self.units.removeAll(keepingCapacity: true)
            } else {
                let count = Int(try reader.read(3, path: paths[at + 1]))
                if count > 4 { throw GesWireError(code: GesWireError.invalidCount, path: paths[at + 1]) }
                self.units.removeAll(keepingCapacity: true)
                for position in 0..<count {
                    if position == self.__unitsPool.count { self.__unitsPool.append(Unit()) }
                    let item = self.__unitsPool[position]
                    try item.__readFields(&reader, paths, at + 3, level + 1)
                    self.units.append(item)
                }
            }
        }

        #if DEBUG || GES_CHECK_SHARING
        @exclusivity(unchecked) var __busy = false

        func __mark(_ busy: Bool) {
            self.__busy = busy
            for item in self.__unitsPool { item.__mark(busy) }
        }

        func __holds() -> Bool {
            if self.__busy { return true }
            for item in self.units where item.__holds() { return true }
            return false
        }
        #endif

        private func __same1(_ baseline: Unit, _ paths: [String], _ at: Int, _ level: Int) throws(GesWireError) -> Bool {
            if level >= 3 {
                if self.units.count + baseline.units.count > 0 { throw GesWireError(code: GesWireError.tooDeep, path: paths[at + 1], detail: "deeper than depth 3") }
            } else {
                if self.units.count != baseline.units.count { return false }
                for index1 in 0..<self.units.count {
                    if !(try self.units[index1].__same(baseline.units[index1], paths, at + 3, level + 1)) { return false }
                }
            }
            return true
        }

        private static func __ascending1(_ list: [Unit], _ paths: [String], _ at: Int) throws(GesWireError) -> Bool {
            var previous: UInt64 = 0
            for position in 0..<list.count {
                let order = try list[position].__keyOrder(paths, at + 3)
                if position > 0 && order <= previous { return false }
                previous = order
            }
            return true
        }

        private func __writeKeyed1(_ baseline: Unit, _ writer: inout GesBitWriter, _ paths: [String], _ at: Int, _ level: Int) throws(GesWireError) -> Bool {
            let list = self.units
            let held = baseline.units
            if level >= 3 {
                if list.count + held.count > 0 { throw GesWireError(code: GesWireError.tooDeep, path: paths[at + 1], detail: "deeper than depth 3") }
                return false
            }
            if list.count > 4 || held.count > 4 { throw GesWireError(code: GesWireError.tooLong, path: paths[at + 1]) }
            let listAscending = try Self.__ascending1(list, paths, at)
            let heldAscending = try Self.__ascending1(held, paths, at)
            if !listAscending || !heldAscending {
                if try __same1(baseline, paths, at, level) { return false }
                try writer.write(1, width: 1)
                if level >= 3 {
                    if list.count > 0 { throw GesWireError(code: GesWireError.tooDeep, path: paths[at + 1], detail: "deeper than depth 3") }
                } else {
                    if list.count > 4 { throw GesWireError(code: GesWireError.tooLong, path: paths[at + 1]) }
                    try writer.write(UInt64(list.count), width: 3)
                    for item in list {
                        try item.__writeFields(&writer, paths, at + 3, level + 1)
                    }
                }
                return true
            }
            let entry = writer.bitPosition
            try writer.write(0, width: 1)
            var countBit = writer.bitPosition
            try writer.write(0, width: 3)
            var removed: UInt64 = 0
            var other = 0
            for position in 0..<held.count {
                let order = try held[position].__keyOrder(paths, at + 3)
                var kept = false
                while other < list.count {
                    let next = try list[other].__keyOrder(paths, at + 3)
                    if next >= order {
                        kept = next == order
                        break
                    }
                    other += 1
                }
                if kept { continue }
                try writer.write(UInt64(position), width: 2)
                removed += 1
            }
            Self.__setCount(&writer, countBit, removed, 3)
            countBit = writer.bitPosition
            try writer.write(0, width: 3)
            var added: UInt64 = 0
            other = 0
            for position in 0..<list.count {
                let order = try list[position].__keyOrder(paths, at + 3)
                var kept = false
                while other < held.count {
                    let next = try held[other].__keyOrder(paths, at + 3)
                    if next >= order {
                        kept = next == order
                        break
                    }
                    other += 1
                }
                if kept { continue }
                try list[position].__writeFields(&writer, paths, at + 3, level + 1)
                added += 1
            }
            Self.__setCount(&writer, countBit, added, 3)
            countBit = writer.bitPosition
            try writer.write(0, width: 3)
            var changed: UInt64 = 0
            other = 0
            for position in 0..<held.count {
                let order = try held[position].__keyOrder(paths, at + 3)
                var kept = false
                while other < list.count {
                    let next = try list[other].__keyOrder(paths, at + 3)
                    if next >= order {
                        kept = next == order
                        break
                    }
                    other += 1
                }
                if !kept { continue }
                let start = writer.bitPosition
                try writer.write(UInt64(position), width: 2)
                if try list[other].__writeDelta(held[position], &writer, paths, at + 3, true, level + 1) {
                    changed += 1
                } else {
                    writer.rewind(to: start)
                }
            }
            Self.__setCount(&writer, countBit, changed, 3)
            if removed > 0 || added > 0 || changed > 0 { return true }
            writer.rewind(to: entry)
            return false
        }

        private func __readKeyed1(_ baseline: Unit, _ reader: inout GesBitReader, _ paths: [String], _ at: Int, _ level: Int) throws(GesWireError) {
            let held = baseline.units
            if level >= 3 {
                self.units.removeAll(keepingCapacity: true)
                if try __same1(baseline, paths, at, level) { throw GesWireError(code: GesWireError.invalidDelta, path: paths[at + 1]) }
                return
            }
            if try reader.read(1, path: paths[at + 1]) == 1 {
                if level >= 3 {
                    self.units.removeAll(keepingCapacity: true)
                } else {
                    let count = Int(try reader.read(3, path: paths[at + 1]))
                    if count > 4 { throw GesWireError(code: GesWireError.invalidCount, path: paths[at + 1]) }
                    self.units.removeAll(keepingCapacity: true)
                    for position in 0..<count {
                        if position == self.__unitsPool.count { self.__unitsPool.append(Unit()) }
                        let item = self.__unitsPool[position]
                        try item.__readFields(&reader, paths, at + 3, level + 1)
                        self.units.append(item)
                    }
                }
                let listAscending = try Self.__ascending1(self.units, paths, at)
                let heldAscending = try Self.__ascending1(held, paths, at)
                if listAscending && heldAscending { throw GesWireError(code: GesWireError.invalidDelta, path: paths[at + 1]) }
                if try __same1(baseline, paths, at, level) { throw GesWireError(code: GesWireError.invalidDelta, path: paths[at + 1]) }
                return
            }
            if !(try Self.__ascending1(held, paths, at)) { throw GesWireError(code: GesWireError.invalidDelta, path: paths[at + 1]) }
            let baselineCount = UInt64(held.count)
            var removedLeft = try reader.read(3, path: paths[at + 1])
            if removedLeft > 4 { throw GesWireError(code: GesWireError.invalidCount, path: paths[at + 1]) }
            var removedCursor = reader.bitPosition
            do {
                var previous: UInt64 = 0
                for item in 0..<removedLeft {
                    let position = try reader.read(2, path: paths[at + 1])
                    if position >= baselineCount || (item > 0 && position <= previous) { throw GesWireError(code: GesWireError.invalidDelta, path: paths[at + 1]) }
                    previous = position
                }
            }
            var addedLeft = try reader.read(3, path: paths[at + 1])
            if addedLeft > 4 { throw GesWireError(code: GesWireError.invalidCount, path: paths[at + 1]) }
            var addedCursor = reader.bitPosition
            do {
                var other = 0
                var previous: UInt64 = 0
                for item in 0..<addedLeft {
                    let start = reader.bitPosition
                    let order = try Unit.__readKeyOrder(&reader, paths, at + 3)
                    if item > 0 && order <= previous { throw GesWireError(code: GesWireError.invalidDelta, path: paths[at + 1]) }
                    previous = order
                    while other < held.count {
                        let next = try held[other].__keyOrder(paths, at + 3)
                        if next == order { throw GesWireError(code: GesWireError.invalidDelta, path: paths[at + 1]) }
                        if next > order { break }
                        other += 1
                    }
                    reader.seek(to: start)
                    if self.__unitsPool.isEmpty { self.__unitsPool.append(Unit()) }
                    try self.__unitsPool[0].__readFields(&reader, paths, at + 3, level + 1)
                }
            }
            var changedLeft = try reader.read(3, path: paths[at + 1])
            if changedLeft > 4 { throw GesWireError(code: GesWireError.invalidCount, path: paths[at + 1]) }
            var changedCursor = reader.bitPosition
            if removedLeft == 0 && addedLeft == 0 && changedLeft == 0 { throw GesWireError(code: GesWireError.invalidDelta, path: paths[at + 1]) }
            if baselineCount - removedLeft + addedLeft > 4 { throw GesWireError(code: GesWireError.invalidDelta, path: paths[at + 1]) }
            self.units.removeAll(keepingCapacity: true)
            var nextRemoved = try Self.__nextPosition(&reader, &removedCursor, &removedLeft, 2, paths[at + 1])
            var nextChanged = try Self.__nextPosition(&reader, &changedCursor, &changedLeft, 2, paths[at + 1])
            var addedOrder: UInt64 = 0
            if addedLeft > 0 {
                reader.seek(to: addedCursor)
                addedOrder = try Unit.__readKeyOrder(&reader, paths, at + 3)
            }
            for position in 0..<baselineCount {
                let element = held[Int(position)]
                let order = try element.__keyOrder(paths, at + 3)
                while addedLeft > 0 && addedOrder < order {
                    if self.units.count == self.__unitsPool.count { self.__unitsPool.append(Unit()) }
                    let item = self.__unitsPool[self.units.count]
                    reader.seek(to: addedCursor)
                    try item.__readFields(&reader, paths, at + 3, level + 1)
                    addedCursor = reader.bitPosition
                    self.units.append(item)
                    addedLeft -= 1
                    if addedLeft > 0 { addedOrder = try Unit.__readKeyOrder(&reader, paths, at + 3) }
                }
                if position == nextRemoved {
                    if position == nextChanged { throw GesWireError(code: GesWireError.invalidDelta, path: paths[at + 1]) }
                    nextRemoved = try Self.__nextPosition(&reader, &removedCursor, &removedLeft, 2, paths[at + 1])
                } else if position == nextChanged {
                    if self.units.count == self.__unitsPool.count { self.__unitsPool.append(Unit()) }
                    let item = self.__unitsPool[self.units.count]
                    reader.seek(to: changedCursor)
                    if !(try item.__readDelta(element, &reader, paths, at + 3, true, level + 1)) { throw GesWireError(code: GesWireError.invalidDelta, path: paths[at + 2]) }
                    changedCursor = reader.bitPosition
                    self.units.append(item)
                    let before = nextChanged
                    nextChanged = try Self.__nextPosition(&reader, &changedCursor, &changedLeft, 2, paths[at + 1])
                    if nextChanged <= before { throw GesWireError(code: GesWireError.invalidDelta, path: paths[at + 1]) }
                } else {
                    if self.units.count == self.__unitsPool.count { self.__unitsPool.append(Unit()) }
                    let item = self.__unitsPool[self.units.count]
                    item.copy(from: element)
                    self.units.append(item)
                }
            }
            // A changed position beyond the baseline was never reached.
            if nextChanged != UInt64.max { throw GesWireError(code: GesWireError.invalidDelta, path: paths[at + 1]) }
            while addedLeft > 0 {
                if self.units.count == self.__unitsPool.count { self.__unitsPool.append(Unit()) }
                let item = self.__unitsPool[self.units.count]
                reader.seek(to: addedCursor)
                try item.__readFields(&reader, paths, at + 3, level + 1)
                addedCursor = reader.bitPosition
                self.units.append(item)
                addedLeft -= 1
                if addedLeft > 0 { addedOrder = try Unit.__readKeyOrder(&reader, paths, at + 3) }
            }
            reader.seek(to: changedCursor)
        }

        private static func __setCount(_ writer: inout GesBitWriter, _ countBit: Int, _ count: UInt64, _ width: Int) {
            for bit in 0..<width where (count >> UInt64(bit)) & 1 != 0 { writer.setBit(countBit + bit) }
        }

        // The next position of a section, read at its cursor, or the largest number when the section has ended.
        private static func __nextPosition(_ reader: inout GesBitReader, _ cursor: inout Int, _ left: inout UInt64, _ width: Int, _ path: String) throws(GesWireError) -> UInt64 {
            if left == 0 { return .max }
            left -= 1
            reader.seek(to: cursor)
            let position = try reader.read(width, path: path)
            cursor = reader.bitPosition
            return position
        }

        private static func __wire0(_ value: Int64, _ paths: [String], _ at: Int) throws(GesWireError) -> UInt64 {
            if value < 0 || UInt64(bitPattern: value) &- 0 > 15 { throw GesWireError(code: GesWireError.outOfRange, path: paths[at + 0]) }
            return UInt64(bitPattern: value) &- 0
        }

        private static func __read0(_ reader: inout GesBitReader, _ paths: [String], _ at: Int) throws(GesWireError) -> UInt64 {
            let wire = try reader.read(4, path: paths[at + 0])
            return wire
        }

        private static func __value0(_ wire: UInt64) -> Int64 { Int64(bitPattern: 0 &+ wire) }

        func __same(_ other: Unit, _ paths: [String], _ at: Int, _ level: Int = 1) throws(GesWireError) -> Bool {
            if try Self.__wire0(self.id, paths, at) != Self.__wire0(other.id, paths, at) { return false }
            if level >= 3 {
                if self.units.count + other.units.count > 0 { throw GesWireError(code: GesWireError.tooDeep, path: paths[at + 1], detail: "deeper than depth 3") }
            } else {
                if self.units.count != other.units.count { return false }
                for index1 in 0..<self.units.count {
                    if !(try self.units[index1].__same(other.units[index1], paths, at + 3, level + 1)) { return false }
                }
            }
            return true
        }

        /// Copies the values of another record into the storage of this one, without allocating once it has grown.
        func copy(from other: Unit) {
            if self === other { return }
            self.id = other.id
            self.units.removeAll(keepingCapacity: true)
            for index1 in 0..<other.units.count {
                if index1 == self.__unitsPool.count { self.__unitsPool.append(Unit()) }
                let item1 = self.__unitsPool[index1]
                item1.copy(from: other.units[index1])
                self.units.append(item1)
            }
        }

        func __quantize(_ paths: [String], _ at: Int, _ level: Int = 1) throws(GesWireError) {
            if level >= 3 {
                if self.units.count > 0 { throw GesWireError(code: GesWireError.tooDeep, path: paths[at + 1], detail: "deeper than depth 3") }
            } else {
                for index1 in 0..<self.units.count {
                    try self.units[index1].__quantize(paths, at + 3, level + 1)
                }
            }
        }

        /// Returns whether another schema has the same wire values, so that it writes the same bytes.
        /// - Throws: `GesWireError` when a compared value has no wire value, such as a number outside its range.
        func wireEquals(_ other: Unit) throws(GesWireError) -> Bool {
            try __same(other, Self.__paths, 0)
        }

        /// Replaces every quantized value by the value its index decodes to, which a receiver reads.
        /// - Throws: `GesWireError` when a quantized value lies outside its range.
        func quantize() throws(GesWireError) {
            try __quantize(Self.__paths, 0)
        }

        func __keyOrder(_ paths: [String], _ at: Int) throws(GesWireError) -> UInt64 {
            try Self.__wire0(self.id, paths, at)
        }

        static func __readKeyOrder(_ reader: inout GesBitReader, _ paths: [String], _ at: Int) throws(GesWireError) -> UInt64 {
            try Self.__read0(&reader, paths, at)
        }

        /// Writes what differs from a baseline, the full record the receiver holds; `maxByteCount` bytes always suffice.
        /// - Returns: The number of bytes written.
        /// - Throws: `GesWireError` when a value does not fit its field, the keys differ, or the buffer is too small.
        func writeDelta(against baseline: Unit, into buffer: UnsafeMutableRawBufferPointer) throws(GesWireError) -> Int {
            var writer = GesBitWriter(into: buffer)
            let paths = Self.__paths
            let key = try Self.__wire0(self.id, paths, 0)
            if try key != Self.__wire0(baseline.id, paths, 0) { throw GesWireError(code: GesWireError.keyMismatch, path: paths[0]) }
            try writer.write(key, width: 4)
            _ = try __writeDelta(baseline, &writer, Self.__paths, 0, true)
            return try writer.finish()
        }

        /// Counts the bytes that `writeDelta(against:into:)` writes against a baseline, without writing them.
        /// - Throws: `GesWireError` when a value does not fit its field or the keys differ.
        func deltaEncodedByteCount(against baseline: Unit) throws(GesWireError) -> Int {
            var writer = GesBitWriter.counting()
            let paths = Self.__paths
            let key = try Self.__wire0(self.id, paths, 0)
            if try key != Self.__wire0(baseline.id, paths, 0) { throw GesWireError(code: GesWireError.keyMismatch, path: paths[0]) }
            try writer.write(key, width: 4)
            _ = try __writeDelta(baseline, &writer, Self.__paths, 0, true)
            return try writer.finish()
        }

        /// Writes what differs from a baseline into a new array of its exact size. A count comes first: it sizes the buffer for
        /// the elements that the writer tries and takes back, so that the largest delta is not allocated.
        /// - Throws: `GesWireError` when a value does not fit its field or the keys differ.
        func deltaEncoded(against baseline: Unit) throws(GesWireError) -> [UInt8] {
            var writer = GesBitWriter.counting()
            let paths = Self.__paths
            let key = try Self.__wire0(self.id, paths, 0)
            if try key != Self.__wire0(baseline.id, paths, 0) { throw GesWireError(code: GesWireError.keyMismatch, path: paths[0]) }
            try writer.write(key, width: 4)
            _ = try __writeDelta(baseline, &writer, Self.__paths, 0, true)
            _ = try writer.finish()
            let buffer = UnsafeMutableRawBufferPointer.allocate(byteCount: Swift.max(writer.requiredByteCount, 1), alignment: 8)
            defer { buffer.deallocate() }
            let count = try writeDelta(against: baseline, into: buffer)
            return Array(buffer[0..<count])
        }

        /// Reads a delta against a baseline into this instance. After an error its values are unspecified.
        /// - Parameters:
        ///   - data: The delta; it may continue after it.
        ///   - baseline: The baseline, another instance.
        ///   - byteLimit: An optional limit on the bytes of this delta.
        /// - Returns: The number of bytes the delta occupies.
        /// - Throws: `GesWireError` when the data is no valid delta for this baseline.
        @discardableResult
        func readDelta(from data: UnsafeRawBufferPointer, against baseline: Unit, byteLimit: Int = .max) throws(GesWireError) -> Int {
            if self === baseline { throw GesWireError(code: GesWireError.overlappingBuffers, path: "") }
            #if DEBUG || GES_CHECK_SHARING
            self.__mark(true)
            let shared = baseline.__holds()
            self.__mark(false)
            if shared { throw GesWireError(code: GesWireError.overlappingBuffers, path: "") }
            #endif
            var reader = GesBitReader(data: data, byteLimit: byteLimit)
            let paths = Self.__paths
            let key = try Self.__read0(&reader, paths, 0)
            if try key != Self.__wire0(baseline.id, paths, 0) { throw GesWireError(code: GesWireError.invalidDelta, path: paths[0]) }
            _ = try __readDelta(baseline, &reader, Self.__paths, 0, true)
            return try reader.finish()
        }

        /// Reads a delta from bytes against a baseline into this instance. After an error its values are unspecified.
        /// - Returns: The number of bytes the delta occupies.
        /// - Throws: `GesWireError` when the bytes are no valid delta for this baseline.
        @discardableResult
        func readDelta(from bytes: [UInt8], against baseline: Unit, byteLimit: Int = .max) throws(GesWireError) -> Int {
            let buffer = UnsafeMutableRawBufferPointer.allocate(byteCount: Swift.max(bytes.count, 1), alignment: 8)
            defer { buffer.deallocate() }
            buffer.copyBytes(from: bytes)
            return try readDelta(from: UnsafeRawBufferPointer(rebasing: buffer[0..<bytes.count]), against: baseline, byteLimit: byteLimit)
        }

        func __writeDelta(_ baseline: Unit, _ writer: inout GesBitWriter, _ paths: [String], _ at: Int, _ top: Bool, _ level: Int = 1) throws(GesWireError) -> Bool {
            let first = writer.bitPosition
            var left = top ? 1 : 2
            while left > 0 {
                try writer.write(0, width: Swift.min(left, 64))
                left -= 64
            }
            var changed = false
            var ordinal = 0
            if !top {
                var set0 = false
                do {
                    let value0 = try Self.__wire0(self.id, paths, at)
                    let held0 = try Self.__wire0(baseline.id, paths, at)
                    if value0 != held0 {
                        try writer.write(value0, width: 4)
                        set0 = true
                    }
                }
                if set0 {
                    writer.setBit(first + ordinal)
                    changed = true
                }
                ordinal += 1
            }
            do {
                var set1 = false
                if try __writeKeyed1(baseline, &writer, paths, at, level) { set1 = true }
                if set1 {
                    writer.setBit(first + ordinal)
                    changed = true
                }
                ordinal += 1
            }
            return changed
        }

        func __readDelta(_ baseline: Unit, _ reader: inout GesBitReader, _ paths: [String], _ at: Int, _ top: Bool, _ level: Int = 1) throws(GesWireError) -> Bool {
            let fieldCount = top ? 1 : 2
            try reader.require(fieldCount, path: at == 0 ? "" : paths[at - 1])
            let changeBits = reader.bitPosition
            reader.seek(to: changeBits + fieldCount)
            var changed = false
            var ordinal = 0
            if !top {
                let payload0 = reader.bitPosition
                reader.seek(to: changeBits + ordinal)
                let set0 = try reader.read(1, path: paths[at + 0]) == 1
                reader.seek(to: payload0)
                if set0 {
                    do {
                        let held0 = try Self.__wire0(baseline.id, paths, at)
                        let value0 = try Self.__read0(&reader, paths, at)
                        if value0 == held0 { throw GesWireError(code: GesWireError.invalidDelta, path: paths[at + 0]) }
                        self.id = Self.__value0(value0)
                    }
                    changed = true
                } else {
                    self.id = baseline.id
                }
                ordinal += 1
            } else {
                self.id = Self.__value0(try Self.__wire0(baseline.id, paths, at))
            }
            do {
